// Prototype: reproduce margin metrics from live public APIs (same math to embed in index.html)
const https = require('https');

function get(url) {
  return new Promise((res, rej) => {
    https.get(url, r => { let b=''; r.on('data',d=>b+=d); r.on('end',()=>res(b)); }).on('error',rej);
  });
}
function jsonp(url) {
  // add callback and strip wrapper
  const cb = 'cb' + Math.floor(Math.random()*1e9);
  return get(url + (url.includes('?')?'&':'?') + 'callback=' + cb)
    .then(t => JSON.parse(t.replace(new RegExp('^'+cb+'\\('), '').replace(/\);?\s*$/, '')));
}
function stdev(xs){ if(xs.length<2) return null; const m=xs.reduce((a,b)=>a+b,0)/xs.length; return Math.sqrt(xs.reduce((a,b)=>a+(b-m)**2,0)/(xs.length-1)); }
function boll(closes,n,k){ if(closes.length<n) return null; const w=closes.slice(-n); const m=w.reduce((a,b)=>a+b,0)/n; const sd=stdev(w); return {n,mid:+m.toFixed(4),sd:+sd.toFixed(4),lower:+(m-k*sd).toFixed(4),cur:closes[closes.length-1],belowLower:closes[closes.length-1]<=m-k*sd}; }
function pctRank(arr,v){ if(v==null||!arr.length) return null; let c=0; for(const x of arr) if(x<=v)c++; return +(c/arr.length*100).toFixed(1); }

const targets = [
  {code:'601000', secid:'1.601000', name:'唐山港', dps:0.2},
  {code:'600461', secid:'1.600461', name:'洪城环境', dps:0.4671},
  {code:'601077', secid:'1.601077', name:'渝农商行', dps:0.3208},
  {code:'601298', secid:'1.601298', name:'青岛港', dps:0.4851},
  {code:'601033', secid:'1.601033', name:'永兴股份', dps:0.6305},
  {code:'000651', secid:'0.000651', name:'格力电器', dps:2.9999},
  {code:'000001', secid:'0.000001', name:'平安银行', dps:0.6093},
  {code:'000598', secid:'0.000598', name:'兴蓉环境', dps:0.2355},
  {code:'000429', secid:'0.000429', name:'粤高速A', dps:0.604},
];
const TARGET_YLD = 5.0, K = 2, PCT_YEARS = 3;

(async () => {
  console.log('name'.padEnd(8), 'price'.padStart(7), 'dps'.padStart(7), 'curYld'.padStart(7), 'avg'.padStart(7), 'pct'.padStart(6), 'tgtAbs'.padStart(7), 'tgtCons'.padStart(8), '  boll20/60');
  for (const t of targets) {
    const beg = new Date(Date.now() - (PCT_YEARS*365 + 30)*864e5).toISOString().slice(0,10).replace(/-/g,'');
    const kurl = `https://push2his.eastmoney.com/api/qt/stock/kline/get?secid=${t.secid}&fields1=f1&fields2=f51,f53&klt=101&fqt=1&beg=${beg}&end=20500101`;
    const kj = JSON.parse(await get(kurl));
    const klines = (kj.data && kj.data.klines) || [];
    const dates = [], closes = [];
    for (const line of klines) { const p=line.split(','); dates.push(p[0]); closes.push(+p[1]); }
    const price = closes[closes.length-1];

    // dividends (per-share = PRETAX_BONUS_RMB/10)
    const durl = `https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_SHAREBONUS_DET&columns=ALL&filter=(SECURITY_CODE%3D%22${t.code}%22)&pageNumber=1&pageSize=100&sortColumns=EX_DIVIDEND_DATE&sortTypes=-1`;
    let dividends = [];
    try {
      const dj = await jsonp(durl);
      for (const row of ((dj.result&&dj.result.data)||[])) {
        if (row.EX_DIVIDEND_DATE && row.PRETAX_BONUS_RMB != null && +row.PRETAX_BONUS_RMB>0)
          dividends.push({ d: row.EX_DIVIDEND_DATE.slice(0,10), v: +row.PRETAX_BONUS_RMB/10 });
      }
    } catch(e) { console.log('  div err', t.name, e.message); }
    dividends.sort((a,b)=>a.d<b.d?-1:1);
    const divDates = dividends.map(x=>x.d);

    // biz
    const boll = [boll(closes,20,K), boll(closes,60,K)].filter(Boolean);
    // historical yield percentile over PCT_YEARS
    const lastDate = dates[dates.length-1];
    const startWin = new Date(new Date(lastDate) - PCT_YEARS*365*864e5).toISOString().slice(0,10);
    const histY = [];
    const bisect = (arr, val) => { let lo=0,hi=arr.length; while(lo<hi){const m=(lo+hi)>>1; if(arr[m]<=val)lo=m+1; else hi=m;} return lo; };
    for (let i=0;i<dates.length;i++){
      const dt=dates[i], px=closes[i];
      if (dt<startWin || !(px>0)) continue;
      const cutD = new Date(new Date(dt) - 365*864e5).toISOString().slice(0,10);
      const lo=bisect(divDates, cutD), hi=bisect(divDates, dt);
      let roll=0; for(let j=lo;j<hi;j++) roll+=dividends[j].v;
      if (roll>0) histY.push(roll/px*100);
    }
    const dpsUsed = t.dps>0 ? t.dps : null;
    const curYld = (dpsUsed && price>0) ? dpsUsed/price*100 : null;
    const yldPct = pctRank(histY, curYld);
    const avg = histY.length ? +(histY.reduce((a,b)=>a+b,0)/histY.length).toFixed(4) : null;
    const tgtAbs = (dpsUsed && TARGET_YLD>0) ? +(dpsUsed/(TARGET_YLD/100)).toFixed(3) : null;
    const tgtCons = (dpsUsed && avg>0) ? +(dpsUsed/(avg*1.1/100)).toFixed(3) : null;
    const b={}; boll.forEach(x=>b[x.n]=x);
    console.log(t.name.padEnd(8), (price||0).toFixed(2).padStart(7), (dpsUsed||0).toFixed(3).padStart(7),
      (curYld||0).toFixed(2).padStart(7), (avg||0).toFixed(2).padStart(7), String(yldPct).padStart(6),
      (tgtAbs||0).toFixed(2).padStart(7), (tgtCons||0).toFixed(2).padStart(8),
      `  ${b[20]?b[20].lower:'-'}/${b[60]?b[60].lower:'-'}`);
  }
})();

// Prototype: reproduce margin metrics from live public APIs (same math to embed in index.html)
const https = require('https');

function get(url) {
  return new Promise((res, rej) => {
    https.get(url, r => { let b = ''; r.on('data', d => b += d); r.on('end', () => res(b)); }).on('error', rej);
  });
}
function jsonp(url) {
  const cb = 'cb' + Math.floor(Math.random() * 1e9);
  return get(url + (url.includes('?') ? '&' : '?') + 'callback=' + cb)
    .then(t => JSON.parse(t.replace(new RegExp('^' + cb + '\\('), '').replace(/\);?\s*$/, '')));
}
function stdev(xs) { if (xs.length < 2) return null; const m = xs.reduce((a, b) => a + b, 0) / xs.length; return Math.sqrt(xs.reduce((a, b) => a + (b - m) ** 2, 0) / (xs.length - 1)); }
function bollCalc(closes, n, k) { if (closes.length < n) return null; const w = closes.slice(-n); const m = w.reduce((a, b) => a + b, 0) / n; const sd = stdev(w); return { n, mid: +m.toFixed(4), sd: +sd.toFixed(4), lower: +(m - k * sd).toFixed(4), cur: closes[closes.length - 1], belowLower: closes[closes.length - 1] <= m - k * sd }; }
function pctRank(arr, v) { if (v == null || !arr.length) return null; let c = 0; for (const x of arr) if (x <= v) c++; return +(c / arr.length * 100).toFixed(1); }

const targets = [
