/* ===== 安全边际指标：页面内实时从东财公开接口计算，无本地数据文件 =====
   - 布林带 20/60 日：push2his kline（前复权，CORS 允许 fetch）
   - 股息率、历史分位：datacenter-web RPT_SHAREBONUS_DET（JSONP 绕 CORS） */
const MARGIN_CACHE_KEY = 'panel_margin_v1';
function _mMean(a) { return a.length ? a.reduce((x, y) => x + y, 0) / a.length : null; }
function _mStdev(a) { if (a.length < 2) return null; const m = _mMean(a); return Math.sqrt(a.reduce((s, x) => s + (x - m) * (x - m), 0) / (a.length - 1)); }
function _mBoll(closes, n, k) {
  if (closes.length < n) return null;
  const w = closes.slice(-n), m = _mMean(w), sd = _mStdev(w);
  if (sd == null) return null;
  const lower = m - k * sd, cur = closes[closes.length - 1];
  return { n: n, mid: +m.toFixed(4), sd: +sd.toFixed(4), lower: +lower.toFixed(4), cur: +cur.toFixed(4),
    belowLower: cur <= lower, distToLowerPct: lower > 0 ? +((cur - lower) / lower * 100).toFixed(2) : null };
}
function _mPctRank(arr, v) { if (v == null || !arr.length) return null; let c = 0; for (const x of arr) if (x <= v) c++; return +(c / arr.length * 100).toFixed(1); }
function _mBisect(arr, val) { let lo = 0, hi = arr.length; while (lo < hi) { const m = (lo + hi) >> 1; if (arr[m] <= val) lo = m + 1; else hi = m; } return lo; }
function _mDateShift(dtStr, days) { const d = new Date(dtStr + 'T00:00:00'); d.setDate(d.getDate() + days); return d.toISOString().slice(0, 10); }

function _mJsonp(url, timeoutMs) {
  return new Promise((resolve, reject) => {
    const cb = 'ovmg' + Math.floor(Math.random() * 1e9);
    const s = document.createElement('script');
    let done = false;
    const timer = setTimeout(() => fin(new Error('timeout')), timeoutMs || 8000);
    function fin(err, data) {
      if (done) return; done = true; clearTimeout(timer);
      try { s.remove(); } catch (e) {}
      try { delete window[cb]; } catch (e) {}
      if (err) reject(err); else resolve(data);
    }
    window[cb] = d => fin(null, d);
    s.onerror = () => fin(new Error('net'));
    s.src = url + (url.indexOf('?') >= 0 ? '&' : '?') + 'callback=' + cb + '&_=' + Date.now();
    (document.head || document.body).appendChild(s);
  });
}

/* 计算单只标的安全边际指标；失败返回 null（页面自动退化为 60 日均价口径） */
function _mComputeOne(t, params) {
  const years = params.pctYears || 3, K = params.bollK || 2;
  const beg = _mDateShift(new Date().toISOString().slice(0, 10), -(years * 365 + 40)).replace(/-/g, '');
  const kurl = 'https://push2his.eastmoney.com/api/qt/stock/kline/get?secid=' + secidOf(t.code) +
    '&fields1=f1&fields2=f51,f53&klt=101&fqt=1&beg=' + beg + '&end=20500101';
  return fetch(kurl, { cache: 'no-store' })
    .then(r => r.json())
    .then(kj => {
      const klines = (kj && kj.data && kj.data.klines) || [];
      if (!klines.length) throw new Error('no kline');
      const dates = [], closes = [];
      klines.forEach(line => { const p = line.split(','); dates.push(p[0]); closes.push(+p[1]); });
      const price = closes[closes.length - 1];
      // 分红（每股 = PRETAX_BONUS_RMB/10）
      const durl = 'https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_SHAREBONUS_DET&columns=ALL&filter=(SECURITY_CODE%3D%22' +
        t.code + '%22)&pageNumber=1&pageSize=100&sortColumns=EX_DIVIDEND_DATE&sortTypes=-1';
      return _mJsonp(durl, 9000).catch(() => null).then(dj => {
        const dividends = [];
        ((dj && dj.result && dj.result.data) || []).forEach(row => {
          if (row.EX_DIVIDEND_DATE && row.PRETAX_BONUS_RMB != null && +row.PRETAX_BONUS_RMB > 0)
            dividends.push({ d: String(row.EX_DIVIDEND_DATE).slice(0, 10), v: +row.PRETAX_BONUS_RMB / 10 });
        });
        dividends.sort((a, b) => a.d < b.d ? -1 : 1);
        const divDates = dividends.map(x => x.d);
        const boll = [_mBoll(closes, 20, K), _mBoll(closes, 60, K)].filter(Boolean);
        // 近 N 年股息率分位：逐交易日重建 滚动12M分红/前复权价
        const lastDate = dates[dates.length - 1];
        const startWin = _mDateShift(lastDate, -Math.round(years * 365));
        const histY = [];
        for (let i = 0; i < dates.length; i++) {
          const dt = dates[i], px = closes[i];
          if (dt < startWin || !(px > 0)) continue;
          const cutD = _mDateShift(dt, -365);
          const lo = _mBisect(divDates, cutD), hi = _mBisect(divDates, dt);
          let roll = 0; for (let j = lo; j < hi; j++) roll += dividends[j].v;
          if (roll > 0) histY.push(roll / px * 100);
        }
        const cfgDps = dpsOf(t, price);
        const curYld = (cfgDps && price > 0) ? cfgDps / price * 100 : null;
        const avg = _mMean(histY);
        const targetYld = params.targetYld || 5.0;
        return {
          code: t.code, name: t.name, asOf: lastDate, price: +price.toFixed(4),
          dps: cfgDps, targetYld: targetYld,
          curYld: curYld != null ? +curYld.toFixed(4) : null,
          yldAvg: avg != null ? +avg.toFixed(4) : null,
          yldPct: _mPctRank(histY, curYld), histYldN: histY.length,
          targetBuyAbsolute: (cfgDps && targetYld > 0) ? +(cfgDps / (targetYld / 100)).toFixed(3) : null,
          targetBuyConservative: (cfgDps && avg > 0) ? +(cfgDps / (avg * 1.1 / 100)).toFixed(3) : null,
          boll: boll
        };
      });
    });
}

/* 拉取全部目标的安全边际指标，填充 MARGIN；当日缓存避免每次 10s 刷新都重算 */
function loadMarginMetrics(force) {
  if (!CFG || !TARGETS.length) return Promise.resolve(0);
  const params = (CFG.margin) || {};
  const today = new Date().toISOString().slice(0, 10);
  if (!force) {
    try {
      const raw = localStorage.getItem(MARGIN_CACHE_KEY);
      if (raw) {
        const c = JSON.parse(raw);
        if (c && c.date === today && c.items && Object.keys(c.items).length) {
          Object.keys(c.items).forEach(k => { MARGIN[k] = c.items[k]; });
          return Promise.resolve(marginCount());
        }
      }
    } catch (e) {}
  }
  // 并发拉取，单只失败不影响其它
  return Promise.all(TARGETS.map(t =>
    _mComputeOne(t, params).then(it => {
      const sym = (t.symbol || (t.code + (String(secidOf(t.code))[0] === '1' ? '.SH' : '.SZ')));
      MARGIN[sym] = it;
      return it;
    }).catch(() => null)
  )).then(list => {
    const items = {};
    Object.keys(MARGIN).forEach(k => { items[k] = MARGIN[k]; });
    try { localStorage.setItem(MARGIN_CACHE_KEY, JSON.stringify({ date: today, items: items })); } catch (e) {}
    return list.filter(Boolean).length;
  });
}

