function startApp() {
  initTheme();
  render();
  refreshQuotes();
  startAuto();
  if (CFG) {
    $('#footNote').innerHTML = '目标配置来自 <code>config.js</code>（基准 ' + esc((CFG.meta && CFG.meta.base) || '—') +
      '，共 ' + TARGETS.length + ' 只目标持仓，生成于 ' + esc((CFG.meta && CFG.meta.generated) || '—') + '）。' +
      '<br><span id="mgFoot"></span>' +
      '<br>持仓、成本、盈亏、分红全部由数据库里的交易流水实时算出来。';
    updateMarginFoot();
    // 启动后异步从公开接口实时计算安全边际指标（当日缓存），算完刷新一次页面
    loadMarginMetrics().then(n => {
      updateMarginFoot();
      if (n) { render(); if (typeof renderPlan === 'function') renderPlan(rowsNow(), totals(rowsNow())); }
    }).catch(() => {});
  } else {
    $('#footNote').textContent = '未找到 config.js，买入推荐与风险预警不可用；持仓/成本/盈亏/分红不受影响。';
  }
  $('#rsec').textContent = (CFG && CFG.market && CFG.market.refresh_sec) || 10;
  $('#verTag').textContent = 'v' + BUILD;
}

function updateMarginFoot() {
  const el = document.getElementById('mgFoot');
  if (!el) return;
  const n = marginCount();
  if (n) {
    el.innerHTML = '安全边际指标（股息率目标买价 / 近3年股息率分位 / 布林带下轨）页面内实时计算，已覆盖 ' + n +
      ' 只（行情/分红来自东财公开接口）。数据湖 PE/PB 暂缺，估值分位以股息率分位替代。';
  } else {
    el.innerHTML = '<span class="tx3">安全边际指标加载中/未取到（依赖东财公开接口），暂按 60 日均价口径。</span>';
  }
}

