// 纯函数：布林带 / 分位 / 均值 / 标准差
ok(typeof P._mBoll === 'function', '存在 _mBoll 计算函数');
const closes = [10, 10.5, 10.2, 9.8, 9.5, 9.4, 9.2, 9.0, 8.8, 8.6, 8.5, 8.4, 8.3, 8.2, 8.1, 8.0, 7.9, 7.8, 7.7, 7.6];
