ok(bb && near(bb.mid, 8.9, 0.001), '布林带均值 = 8.9 → ' + (bb && bb.mid));
ok(bb && typeof bb.lower === 'number' && bb.lower < bb.mid, '布林下轨 < 中轨（降序序列）');
ok(bb && bb.belowLower === (closes[closes.length - 1] <= bb.lower), '布林下轨触发判定一致');
const pr = P._mPctRank([1, 2, 3, 4, 5], 4);
ok(near(pr, 80, 0.1), '分位计算：4 在 [1..5] = 80% → ' + pr);
ok(P._mPctRank([], 3) === null, '空序列分位返回 null');
