         { n: 60, mid: 8.88, sd: 0.14, lower: 8.59, cur: 8.56, belowLower: true, distToLowerPct: -0.3 }]
});
// 唐山港：现价 4.80 > 目标买价 4.00 → 不达标，不应买
P._setMargin('601000.SH', {
  code: '601000', name: '唐山港', price: 4.80, dps: 0.2, targetYld: 5.0,
  curYld: 4.17, yldAvg: 5.07, yldPct: 3.2, targetBuyAbsolute: 4.00, targetBuyConservative: 3.59,
  boll: [{ n: 60, mid: 4.5, sd: 0.14, lower: 4.35, cur: 4.80, belowLower: false, distToLowerPct: 10.3 }]
});
ok(P.marginCount() === 2, '已注入 2 条合成指标 → ' + P.marginCount());
