ok(hc && hc.yldHit === true, '洪城环境现价低于目标买价 → 股息率达标可买');
ok(hc && hc.bollHit === true, '洪城环境触及 60 日布林下轨 → bollHit');
ok(tg && tg.yldHit === false, '唐山港现价高于目标买价 → 不达标');

