// Verify the ACTUAL embedded code in index.html computes live metrics correctly.
const fs = require('fs');
const html = fs.readFileSync('分析产出/持仓面板/index.html', 'utf8');
// grab the margin helper block + secidOf + dpsOf by running the whole main script in a vm sandbox
const vm = require('vm');
const m = html.match(/<script>\n\(function \(\) \{\n'use strict';\n\n\/\* =+ 常量[\s\S]*?<\/script>/);
const main = m[0].replace(/^<script>\n/, '').replace(/<\/script>$/, '');
const cfg = fs.readFileSync('分析产出/持仓面板/config.js', 'utf8');
const https = require('https');
function get(url){return new Promise((res,rej)=>{https.get(url,r=>{let b='';r.on('data',d=>b+=d);r.on('end',()=>res(b));}).on('error',rej);});}
const els={};
function el(id){ if(!els[id])els[id]={innerHTML:'',textContent:'',value:'',style:{},classList:{toggle(){},add(){},remove(){},contains(){return false}},addEventListener(){},setAttribute(){},querySelector(){return null},closest(){return null},focus(){}}; return els[id]; }
const sandbox={
  console,Date,Math,Number,String,Object,Array,JSON,isNaN,isFinite,parseFloat,parseInt,RegExp,
  atob:s=>Buffer.from(s,'base64').toString('binary'),
  setTimeout:(f)=>setTimeout(f,9000),clearTimeout:(t)=>clearTimeout(t),setInterval:()=>0,clearInterval:()=>{},
  confirm:()=>true,alert:()=>{},
  indexedDB:{open(){return{}}},localStorage:{getItem:()=>null,setItem:()=>{}},
  document:{getElementById:el,querySelector:s=>el(s.replace(/^#/,'')),querySelectorAll:()=>[],addEventListener:()=>{},createElement:()=>({style:{},dataset:{},remove(){},click(){},appendChild(){},setAttribute(){},onload:null,onerror:null}),head:{appendChild(s){ if(s.src){ get(s.src.replace(/&callback=([^&]+)/,'')).catch(()=>{}); } }},body:{appendChild(){}}},
  // fetch shim for node
  fetch:(url)=>get(url).then(t=>({json:()=>JSON.parse(t)})),
  location:{search:''},FileReader:function(){},Blob:function(){},URL:{createObjectURL:()=>'',revokeObjectURL(){}},
};
sandbox.window=sandbox;sandbox.self=sandbox;sandbox.globalThis=sandbox;
vm.createContext(sandbox);
vm.runInContext(cfg,sandbox);
// minimal sql.js loader stub just to satisfy init (we won't open db)
sandbox.initSqlJs=async()=>({Database:function(){}});
vm.runInContext(main,sandbox);
const P=sandbox.__PANEL__;
const params=(sandbox.PANEL_CONFIG.margin)||{};
(async()=>{
  const t={code:'600461',symbol:'600461.SH',name:'洪城环境',dps:0.4671,secid:'1.600461'};
  const it=await P._mComputeOne(t,params);
  console.log('embedded _mComputeOne → 洪城环境:');
  console.log(JSON.stringify(it,null,1));
  const ok = it && it.targetBuyAbsolute>0 && it.yldPct!=null && it.boll.length>=1;
  console.log('OK=',ok);
  process.exit(ok?0:1);
})().catch(e=>{console.error(e);process.exit(1);});

